import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {ObservableComponent} from "./observable.component";
import {OBSERVABLE_ACTION, OBSERVABLE_CARD} from "./observable.types";

export * from "./observable.types";

registerCardComponent({
  name: OBSERVABLE_CARD,
  component: ObservableComponent,
  events: actionTypesToEvents(OBSERVABLE_ACTION),
});

import * as React from "react";

import {Card, type PiCardProps} from "@pihanga2/core";
import type {
  ObservableEnabledEvents,
  ObservableEvents,
  ObservableKeyEvent,
  ObservableMouseEvent,
  ObservableProps,
  ObservableWheelEvent,
} from "./observable.types";

function pointerPosition(
  e: {pageX: number; pageY: number},
  rect: DOMRect,
): {
  absoluteX: number;
  absoluteY: number;
  relativeX: number;
  relativeY: number;
} {
  return {
    absoluteX: e.pageX,
    absoluteY: e.pageY,
    relativeX: e.pageX - (rect.left + window.scrollX),
    relativeY: e.pageY - (rect.top + window.scrollY),
  };
}

export const ObservableComponent = (
  props: PiCardProps<ObservableProps, ObservableEvents>,
): React.ReactNode => {
  const {
    id,
    content,
    enable = {} as ObservableEnabledEvents,
    className,
    style,
    data,
    cardName,
    onClicked,
    onDoubleClicked,
    onMouseDown,
    onMouseUp,
    onMouseEnter,
    onMouseMove,
    onMouseLeave,
    onContextMenu,
    onWheel,
    onKeyDown,
    onKeyUp,
    onFocus,
    onBlur,
  } = props;

  const rootRef = React.useRef<HTMLDivElement>(null);

  function mouseEvent(
    e: React.MouseEvent<HTMLDivElement>,
  ): ObservableMouseEvent {
    const rect =
      rootRef.current?.getBoundingClientRect() ??
      ({
        left: 0,
        top: 0,
      } as DOMRect);
    return {
      id,
      button: e.button,
      buttons: e.buttons,
      altKey: e.altKey,
      ctrlKey: e.ctrlKey,
      metaKey: e.metaKey,
      shiftKey: e.shiftKey,
      ...pointerPosition(e, rect),
    };
  }

  function wheelEvent(
    e: React.WheelEvent<HTMLDivElement>,
  ): ObservableWheelEvent {
    const rect =
      rootRef.current?.getBoundingClientRect() ??
      ({
        left: 0,
        top: 0,
      } as DOMRect);
    return {
      id,
      deltaX: e.deltaX,
      deltaY: e.deltaY,
      deltaZ: e.deltaZ,
      ...pointerPosition(e, rect),
    };
  }

  function keyEvent(
    e: React.KeyboardEvent<HTMLDivElement>,
  ): ObservableKeyEvent {
    return {
      id,
      key: e.key,
      code: e.code,
      repeat: e.repeat,
      altKey: e.altKey,
      ctrlKey: e.ctrlKey,
      metaKey: e.metaKey,
      shiftKey: e.shiftKey,
    };
  }

  const dataAttrs = data
    ? Object.fromEntries(Object.entries(data).map(([k, v]) => [`data-${k}`, v]))
    : {};

  // Only wire up handlers for events that are explicitly enabled.
  const handlers: Record<string, unknown> = {};

  if (enable.clicked) {
    handlers.onClick = (e: React.MouseEvent<HTMLDivElement>) =>
      onClicked(mouseEvent(e));
  }
  if (enable.doubleClicked) {
    handlers.onDoubleClick = (e: React.MouseEvent<HTMLDivElement>) =>
      onDoubleClicked(mouseEvent(e));
  }
  if (enable.mouseDown) {
    handlers.onMouseDown = (e: React.MouseEvent<HTMLDivElement>) =>
      onMouseDown(mouseEvent(e));
  }
  if (enable.mouseUp) {
    handlers.onMouseUp = (e: React.MouseEvent<HTMLDivElement>) =>
      onMouseUp(mouseEvent(e));
  }
  if (enable.mouseEnter) {
    handlers.onMouseEnter = (e: React.MouseEvent<HTMLDivElement>) =>
      onMouseEnter(mouseEvent(e));
  }
  if (enable.mouseMove) {
    handlers.onMouseMove = (e: React.MouseEvent<HTMLDivElement>) =>
      onMouseMove(mouseEvent(e));
  }
  if (enable.mouseLeave) {
    handlers.onMouseLeave = (e: React.MouseEvent<HTMLDivElement>) =>
      onMouseLeave(mouseEvent(e));
  }
  if (enable.contextMenu) {
    handlers.onContextMenu = (e: React.MouseEvent<HTMLDivElement>) =>
      onContextMenu(mouseEvent(e));
  }
  if (enable.wheel) {
    handlers.onWheel = (e: React.WheelEvent<HTMLDivElement>) =>
      onWheel(wheelEvent(e));
  }
  if (enable.keyDown) {
    handlers.onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) =>
      onKeyDown(keyEvent(e));
  }
  if (enable.keyUp) {
    handlers.onKeyUp = (e: React.KeyboardEvent<HTMLDivElement>) =>
      onKeyUp(keyEvent(e));
  }
  if (enable.focus) {
    handlers.onFocus = () => onFocus({id});
  }
  if (enable.blur) {
    handlers.onBlur = () => onBlur({id});
  }

  // Keyboard events require the element to be focusable.
  const needsTabIndex = Boolean(
    enable.keyDown || enable.keyUp || enable.focus || enable.blur,
  );

  return (
    <div
      ref={rootRef}
      className={className}
      style={style as React.CSSProperties}
      data-pihanga={cardName}
      tabIndex={needsTabIndex ? 0 : undefined}
      {...dataAttrs}
      {...handlers}
    >
      {content && <Card cardName={content} parentCard={cardName} />}
    </div>
  );
};

import {
  type PiCardRef,
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const OBSERVABLE_CARD = "shad/observable";

export const Observable = createCardDeclaration<
  ObservableProps,
  ObservableEvents
>(OBSERVABLE_CARD);

// ---------------------------------------------------------------------------
// Actions
// ---------------------------------------------------------------------------

export const OBSERVABLE_ACTION = registerActions(OBSERVABLE_CARD, [
  "clicked",
  "double_clicked",
  "mouse_down",
  "mouse_up",
  "mouse_enter",
  "mouse_move",
  "mouse_leave",
  "context_menu",
  "wheel",
  "key_down",
  "key_up",
  "focus",
  "blur",
]);

export const onObservableClicked = createOnAction<ObservableMouseEvent>(
  OBSERVABLE_ACTION.CLICKED,
);
export const onObservableDoubleClicked = createOnAction<ObservableMouseEvent>(
  OBSERVABLE_ACTION.DOUBLE_CLICKED,
);
export const onObservableMouseDown = createOnAction<ObservableMouseEvent>(
  OBSERVABLE_ACTION.MOUSE_DOWN,
);
export const onObservableMouseUp = createOnAction<ObservableMouseEvent>(
  OBSERVABLE_ACTION.MOUSE_UP,
);
export const onObservableMouseEnter = createOnAction<ObservableMouseEvent>(
  OBSERVABLE_ACTION.MOUSE_ENTER,
);
export const onObservableMouseMove = createOnAction<ObservableMouseEvent>(
  OBSERVABLE_ACTION.MOUSE_MOVE,
);
export const onObservableMouseLeave = createOnAction<ObservableMouseEvent>(
  OBSERVABLE_ACTION.MOUSE_LEAVE,
);
export const onObservableContextMenu = createOnAction<ObservableMouseEvent>(
  OBSERVABLE_ACTION.CONTEXT_MENU,
);
export const onObservableWheel = createOnAction<ObservableWheelEvent>(
  OBSERVABLE_ACTION.WHEEL,
);
export const onObservableKeyDown = createOnAction<ObservableKeyEvent>(
  OBSERVABLE_ACTION.KEY_DOWN,
);
export const onObservableKeyUp = createOnAction<ObservableKeyEvent>(
  OBSERVABLE_ACTION.KEY_UP,
);
export const onObservableFocus = createOnAction<ObservableFocusEvent>(
  OBSERVABLE_ACTION.FOCUS,
);
export const onObservableBlur = createOnAction<ObservableFocusEvent>(
  OBSERVABLE_ACTION.BLUR,
);

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

/**
 * Flags to selectively enable interaction events on the `Observable` card.
 *
 * An event is only wired up (listened for on the DOM) **and** reported (its
 * `onXxx` callback fired) when its corresponding flag is `true`. Disabled
 * events incur zero overhead — no listener is even attached.
 */
export type ObservableEnabledEvents = {
  /** Single click. */
  clicked?: boolean;
  /** Double click. */
  doubleClicked?: boolean;
  /** Mouse button pressed down. */
  mouseDown?: boolean;
  /** Mouse button released. */
  mouseUp?: boolean;
  /** Pointer entered the bounding box. */
  mouseEnter?: boolean;
  /** Pointer moved while inside the bounding box. */
  mouseMove?: boolean;
  /** Pointer left the bounding box. */
  mouseLeave?: boolean;
  /** Right-click / context-menu request. */
  contextMenu?: boolean;
  /** Mouse wheel / trackpad scroll. */
  wheel?: boolean;
  /** Key pressed down (requires the root to be focused). */
  keyDown?: boolean;
  /** Key released (requires the root to be focused). */
  keyUp?: boolean;
  /** Root element gained focus. */
  focus?: boolean;
  /** Root element lost focus. */
  blur?: boolean;
};

export type ObservableProps<S = object> = {
  /** Optional caller-defined id, echoed back in every emitted event. */
  id?: string;

  /** Single child card rendered inside the transparent wrapper `<div>`. */
  content?: PiCardRef;

  /**
   * Selectively enable which interaction events are captured and reported.
   * Any event not set to `true` here is neither listened for nor emitted.
   */
  enable?: ObservableEnabledEvents;

  /** Additional Tailwind / CSS utility classes for the wrapper `<div>`. */
  className?: string;
  /** Inline style object for the wrapper `<div>`. */
  style?: S;

  /** Arbitrary data attributes rendered as `data-{key}={value}` on the root element */
  data?: Record<string, string>;
};

// ---------------------------------------------------------------------------
// Event payloads
// ---------------------------------------------------------------------------

/**
 * Pointer position reported by every mouse/wheel event.
 *
 * - `absoluteX` / `absoluteY` — relative to the top-left of the **page**
 *   (i.e. `event.pageX` / `event.pageY`; includes scroll offset).
 * - `relativeX` / `relativeY` — relative to the top-left of the
 *   `Observable` card's own bounding box.
 */
export type ObservablePointerPosition = {
  absoluteX: number;
  absoluteY: number;
  relativeX: number;
  relativeY: number;
};

export type ObservableMouseEvent = ObservablePointerPosition & {
  id?: string;
  /** Mouse button that triggered the event (`MouseEvent.button`). */
  button?: number;
  /** Bitmask of currently-pressed buttons (`MouseEvent.buttons`). */
  buttons?: number;
  altKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
};

export type ObservableWheelEvent = ObservablePointerPosition & {
  id?: string;
  deltaX: number;
  deltaY: number;
  deltaZ: number;
};

export type ObservableKeyEvent = {
  id?: string;
  key: string;
  code: string;
  repeat: boolean;
  altKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
};

export type ObservableFocusEvent = {
  id?: string;
};

export type ObservableEvents = {
  onClicked: ObservableMouseEvent;
  onDoubleClicked: ObservableMouseEvent;
  onMouseDown: ObservableMouseEvent;
  onMouseUp: ObservableMouseEvent;
  onMouseEnter: ObservableMouseEvent;
  onMouseMove: ObservableMouseEvent;
  onMouseLeave: ObservableMouseEvent;
  onContextMenu: ObservableMouseEvent;
  onWheel: ObservableWheelEvent;
  onKeyDown: ObservableKeyEvent;
  onKeyUp: ObservableKeyEvent;
  onFocus: ObservableFocusEvent;
  onBlur: ObservableFocusEvent;
};
